 class SignalListener extends PhoneStateListener{public void onSignalStrengthsChanged(SignalStrength strength){signal=strength==null?-1:strength.getLevel();a.view.invalidate();}public void onServiceStateChanged(ServiceState state){serving=state!=null&&state.getState()==ServiceState.STATE_IN_SERVICE;if(!serving){network="";signal=0;}a.view.invalidate();}public void onDataConnectionStateChanged(int state,int type){if(android.os.Build.VERSION.SDK_INT<30)network=networkName(type);a.view.invalidate();}}
 class DisplayListener extends SignalListener{public void onDisplayInfoChanged(TelephonyDisplayInfo info){int override=info.getOverrideNetworkType();network=override==TelephonyDisplayInfo.OVERRIDE_NETWORK_TYPE_NR_NSA?"5G":override==TelephonyDisplayInfo.OVERRIDE_NETWORK_TYPE_NR_ADVANCED?"5G+":override==TelephonyDisplayInfo.OVERRIDE_NETWORK_TYPE_LTE_CA?"4G+":override==TelephonyDisplayInfo.OVERRIDE_NETWORK_TYPE_LTE_ADVANCED_PRO?"4G+":networkName(info.getNetworkType());a.view.invalidate();}}
 void connect(){int sub=SubscriptionManager.getDefaultDataSubscriptionId();boolean allowed=permitted();if(phone!=null&&subscription==sub&&listener!=null&&registeredPermission==allowed)return;stop();subscription=sub;registeredPermission=allowed;signal=-1;network="";try{phone=a.getSystemService(TelephonyManager.class);if(SubscriptionManager.isValidSubscriptionId(sub))phone=phone.createForSubscriptionId(sub);listener=android.os.Build.VERSION.SDK_INT>=30?new DisplayListener():new SignalListener();int flags=PhoneStateListener.LISTEN_SIGNAL_STRENGTHS|PhoneStateListener.LISTEN_SERVICE_STATE|PhoneStateListener.LISTEN_DATA_CONNECTION_STATE;if(android.os.Build.VERSION.SDK_INT>=30&&allowed)flags|=PhoneStateListener.LISTEN_DISPLAY_INFO_CHANGED;phone.listen(listener,flags);if(android.os.Build.VERSION.SDK_INT>=28){SignalStrength strength=phone.getSignalStrength();if(strength!=null)signal=strength.getLevel();}if(allowed)network=networkName(phone.getDataNetworkType());}catch(Exception e){android.util.Log.w("OrbitStatus","Cell status unavailable",e);}}
